import type { BuildOptions, Page } from './types';

export interface PluginContext {
  options: BuildOptions;
  pages: Page[];
  outputs: Map<string, string>;
  shared: Map<string, unknown>;
}

export interface Plugin {
  name: string;
  onStart?(ctx: PluginContext): void | Promise<void>;
  beforeBuild?(ctx: PluginContext): void | Promise<void>;
  afterBuild?(ctx: PluginContext): void | Promise<void>;
  onFile?(page: Page, ctx: PluginContext): void | Promise<void>;
  onEnd?(ctx: PluginContext): void | Promise<void>;
}

export class PluginPipeline {
  private readonly _plugins: Plugin[] = [];

  get plugins(): Plugin[] {
    return this._plugins;
  }

  use(plugin: Plugin): PluginPipeline {
    this._plugins.push(plugin);
    return this;
  }

  async runStart(ctx: PluginContext): Promise<void> {
    for (const plugin of this._plugins) {
      if (plugin.onStart) {
        await plugin.onStart(ctx);
      }
    }
  }

  async runBeforeBuild(ctx: PluginContext): Promise<void> {
    for (const plugin of this._plugins) {
      if (plugin.beforeBuild) {
        await plugin.beforeBuild(ctx);
      }
    }
  }

  async runOnFile(page: Page, ctx: PluginContext): Promise<void> {
    for (const plugin of this._plugins) {
      if (plugin.onFile) {
        await plugin.onFile(page, ctx);
      }
    }
  }

  async runAfterBuild(ctx: PluginContext): Promise<void> {
    for (const plugin of this._plugins) {
      if (plugin.afterBuild) {
        await plugin.afterBuild(ctx);
      }
    }
  }

  async runOnEnd(ctx: PluginContext): Promise<void> {
    for (const plugin of this._plugins) {
      if (plugin.onEnd) {
        await plugin.onEnd(ctx);
      }
    }
  }
}

import type { Page } from './types';

export function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function pagePath(page: Page): string {
  return `${page.slug}.html`;
}

export function renderDocument(page: Page, content: string): string {
  const dateHtml = page.date
    ? `<p class="date"><time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time></p>`
    : '';
  const tagsHtml =
    page.tags.length > 0
      ? `<p class="tags">${page.tags
          .map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`)
          .join(' ')}</p>`
      : '';
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(page.title)}</title>
</head>
<body>
  <header>
    <nav><a href="index.html">Home</a></nav>
    <h1>${escapeHtml(page.title)}</h1>
    ${dateHtml}
  </header>
  <main>
${content}
${tagsHtml}
  </main>
</body>
</html>
`;
}

export function renderPage(page: Page): string {
  return renderDocument(page, page.html);
}

export function renderIndexItems(pages: Page[]): string {
  return [...pages]
    .sort((a, b) => (b.date ?? '').localeCompare(a.date ?? ''))
    .map((page) => {
      const date = page.date
        ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>`
        : '';
      const tags =
        page.tags.length > 0
          ? ` <span class="tags">${page.tags.map((tag) => escapeHtml(tag)).join(', ')}</span>`
          : '';
      return `    <li><a href="${pagePath(page)}">${escapeHtml(page.title)}</a>${date}${tags}</li>`;
    })
    .join('\n');
}

export function renderIndexBody(pages: Page[]): string {
  return `    <ul>\n${renderIndexItems(pages)}\n    </ul>`;
}

export function renderIndex(pages: Page[]): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Index</title>
</head>
<body>
  <header>
    <h1>Index</h1>
  </header>
  <main>
${renderIndexBody(pages)}
  </main>
</body>
</html>
`;
}

import { promises as fs } from 'fs';
import * as path from 'path';
import { marked } from 'marked';
import matter from 'gray-matter';

import type { Page } from '../types';
import type { Plugin, PluginContext } from '../plugin';

export function slugify(name: string): string {
  return name
    .replace(/\.md$/i, '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) {
    return tags.map((tag) => String(tag)).filter((tag) => tag.length > 0);
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((tag) => tag.trim())
      .filter((tag) => tag.length > 0);
  }
  return [];
}

export async function listMarkdownFiles(contentDir: string): Promise<string[]> {
  const entries = await fs.readdir(contentDir, { withFileTypes: true });
  const files: string[] = [];
  for (const entry of entries) {
    const fullPath = path.join(contentDir, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await listMarkdownFiles(fullPath)));
    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
      files.push(fullPath);
    }
  }
  return files.sort();
}

export async function parseMarkdownFile(filePath: string): Promise<Page> {
  const raw = await fs.readFile(filePath, 'utf8');
  const parsed = matter(raw);
  const frontmatter = parsed.data ?? {};
  const baseName = path.basename(filePath);
  const slug = slugify(baseName);
  const title =
    typeof frontmatter.title === 'string' && frontmatter.title.trim().length > 0
      ? frontmatter.title.trim()
      : baseName.replace(/\.md$/i, '');
  const rawDate = frontmatter.date;
  const date =
    typeof rawDate === 'string' && rawDate.trim().length > 0
      ? rawDate.trim()
      : rawDate instanceof Date && !isNaN(rawDate.getTime())
        ? rawDate.toISOString().slice(0, 10)
        : undefined;
  const template =
    typeof frontmatter.template === 'string' && frontmatter.template.trim().length > 0
      ? frontmatter.template.trim()
      : undefined;
  const layout =
    typeof frontmatter.layout === 'string' && frontmatter.layout.trim().length > 0
      ? frontmatter.layout.trim()
      : undefined;
  const html = await marked.parse(parsed.content);
  return {
    slug,
    title,
    date,
    tags: normalizeTags(frontmatter.tags),
    content: parsed.content,
    html,
    template,
    layout,
    data: frontmatter,
  };
}

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  async beforeBuild(ctx: PluginContext): Promise<void> {
    const files = await listMarkdownFiles(ctx.options.contentDir);
    const pages: Page[] = [];
    for (const file of files) {
      pages.push(await parseMarkdownFile(file));
    }
    ctx.pages.push(...pages);
  }
}

import type { Page } from '../types';
import type { Plugin, PluginContext } from '../plugin';
import {
  loadTemplateEngine,
  renderPageWithTemplates,
  renderIndexWithTemplates,
  type FallbackRenderers,
  type TemplateEngine,
} from '../templates';
import {
  pagePath,
  renderDocument,
  renderIndex,
  renderIndexBody,
  renderPage,
} from '../render';

const fallbacks: FallbackRenderers = {
  document: renderDocument,
  indexBody: renderIndexBody,
  indexDocument: renderIndex,
};

export class TemplatePlugin implements Plugin {
  name = 'templates';

  async beforeBuild(ctx: PluginContext): Promise<void> {
    const engine = await loadTemplateEngine(ctx.options.templateDir ?? 'templates');
    ctx.shared.set('templateEngine', engine);
  }

  async onFile(page: Page, ctx: PluginContext): Promise<void> {
    const engine = ctx.shared.get('templateEngine') as TemplateEngine | null | undefined;
    const html = engine ? renderPageWithTemplates(page, engine, fallbacks) : renderPage(page);
    ctx.outputs.set(pagePath(page), html);
  }

  async afterBuild(ctx: PluginContext): Promise<void> {
    const engine = ctx.shared.get('templateEngine') as TemplateEngine | null | undefined;
    const html = engine
      ? renderIndexWithTemplates(ctx.pages, engine, fallbacks)
      : renderIndex(ctx.pages);
    ctx.outputs.set('index.html', html);
  }
}

import { promises as fs } from 'fs';
import * as http from 'http';
import * as path from 'path';
import * as url from 'url';
import chokidar, { type FSWatcher } from 'chokidar';
import { WebSocketServer } from 'ws';

import type { Plugin, PluginContext } from '../plugin';
import type { SSGEngine } from '../engine';

export interface ServeOptions {
  command: 'serve';
  contentDir: string;
  outputDir: string;
  templateDir: string;
  port: number;
}

export interface DevServer {
  server: http.Server;
  wss: WebSocketServer;
  watcher: FSWatcher;
  port: number;
  outputDir: string;
  close(): Promise<void>;
}

export const RELOAD_PATH = '/__livereload';

export const RELOAD_SCRIPT = `<script id="ssg-live-reload">
(function () {
  var scheme = location.protocol === 'https:' ? 'wss:' : 'ws:';
  var socket = new WebSocket(scheme + '//' + location.host + '${RELOAD_PATH}');
  socket.onmessage = function (event) {
    if (event.data === 'reload') {
      location.reload();
    }
  };
  socket.onclose = function () {
    setTimeout(function () {
      location.reload();
    }, 500);
  };
})();
</script>`;

export function injectReloadScript(html: string): string {
  if (html.includes('ssg-live-reload')) {
    return html;
  }
  const index = html.lastIndexOf('</body>');
  if (index === -1) {
    return `${html}\n${RELOAD_SCRIPT}\n`;
  }
  return `${html.slice(0, index)}${RELOAD_SCRIPT}${html.slice(index)}`;
}

const CONTENT_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.md': 'text/markdown; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
};

function contentTypeFor(filePath: string): string {
  return CONTENT_TYPES[path.extname(filePath).toLowerCase()] ?? 'application/octet-stream';
}

function createRequestHandler(outputDir: string) {
  const root = path.resolve(outputDir);
  return async (req: http.IncomingMessage, res: http.ServerResponse): Promise<void> => {
    let pathname = '/';
    try {
      pathname = decodeURIComponent(url.parse(req.url ?? '/').pathname ?? '/');
    } catch {
      // fall through with '/'
    }
    const relative = pathname === '/' ? 'index.html' : pathname.replace(/^\/+/, '');
    const filePath = path.normalize(path.join(root, relative));
    if (!filePath.startsWith(root + path.sep)) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
      return;
    }
    try {
      const data = await fs.readFile(filePath);
      const isHtml = /\.html?$/i.test(relative);
      const body = isHtml ? injectReloadScript(data.toString('utf8')) : data;
      res.writeHead(200, { 'Content-Type': contentTypeFor(filePath) });
      res.end(body);
    } catch {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
    }
  };
}

export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  private server: http.Server | null = null;
  private wss: WebSocketServer | null = null;
  private watcher: FSWatcher | null = null;
  private rebuilding = false;
  private queued = false;

  afterBuild(_ctx: PluginContext): void {
    this.broadcastReload();
  }

  private broadcastReload(): void {
    if (!this.wss) {
      return;
    }
    for (const client of this.wss.clients) {
      if (client.readyState === client.OPEN) {
        client.send('reload');
      }
    }
  }

  private async rebuild(options: ServeOptions, engine: SSGEngine): Promise<void> {
    if (this.rebuilding) {
      this.queued = true;
      return;
    }
    this.rebuilding = true;
    try {
      const rebuilt = await engine.build(options);
      console.log(`Rebuilt ${rebuilt.length} page(s)`);
    } catch (err) {
      console.error(`Rebuild failed: ${(err as Error).message}`);
    } finally {
      this.rebuilding = false;
      if (this.queued) {
        this.queued = false;
        void this.rebuild(options, engine);
      }
    }
  }

  async start(options: ServeOptions, engine: SSGEngine): Promise<DevServer> {
    this.server = null;
    this.wss = null;
    this.watcher = null;
    this.rebuilding = false;
    this.queued = false;

    const pages = await engine.build(options);
    console.log(`Built ${pages.length} page(s) into ${path.resolve(options.outputDir)}`);

    const server = http.createServer(createRequestHandler(options.outputDir));
    const wss = new WebSocketServer({ server, path: RELOAD_PATH });
    const watcher = chokidar.watch([options.contentDir, options.templateDir], {
      ignoreInitial: true,
    });
    this.server = server;
    this.wss = wss;
    this.watcher = watcher;

    watcher.on('all', () => {
      void this.rebuild(options, engine);
    });

    await new Promise<void>((resolve) => {
      const timer = setTimeout(resolve, 2000);
      watcher.once('ready', () => {
        clearTimeout(timer);
        resolve();
      });
    });

    await new Promise<void>((resolve, reject) => {
      const onError = (err: Error): void => {
        server.off('listening', onListening);
        reject(err);
      };
      const onListening = (): void => {
        server.off('error', onError);
        resolve();
      };
      server.once('error', onError);
      server.once('listening', onListening);
      server.listen(options.port);
    });

    const address = server.address();
    const port =
      typeof address === 'object' && address !== null ? address.port : options.port;

    return {
      server,
      wss,
      watcher,
      port,
      outputDir: options.outputDir,
      close: () => this.close(),
    };
  }

  async close(): Promise<void> {
    if (this.wss) {
      for (const client of this.wss.clients) {
        client.terminate();
      }
      await new Promise<void>((resolveClose) => {
        this.wss!.close(() => resolveClose());
      });
      this.wss = null;
    }
    if (this.watcher) {
      await this.watcher.close();
      this.watcher = null;
    }
    if (this.server) {
      this.server.closeAllConnections();
      await new Promise<void>((resolveClose) => {
        this.server!.close(() => resolveClose());
      });
      this.server = null;
    }
  }
}

import { promises as fs } from 'fs';
import * as path from 'path';

import type { BuildOptions, Page } from './types';
import { PluginPipeline, type Plugin, type PluginContext } from './plugin';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/templates';

export interface SSGConfig {
  plugins?: Plugin[];
}

export interface EngineOptions extends BuildOptions {
  configFile?: string;
}

export function defaultPlugins(): Plugin[] {
  return [new MarkdownPlugin(), new TemplatePlugin()];
}

export async function loadConfig(configFile?: string): Promise<SSGConfig | null> {
  const file = configFile ?? 'ssg.config';
  const resolved = path.resolve(process.cwd(), file);
  try {
    const loaded = require(resolved) as { default?: SSGConfig; config?: SSGConfig } | SSGConfig;
    const cfg = ((loaded as { default?: SSGConfig }).default ??
      (loaded as { config?: SSGConfig }).config ??
      loaded) as SSGConfig;
    if (cfg && typeof cfg === 'object' && Array.isArray(cfg.plugins)) {
      return cfg;
    }
    return null;
  } catch {
    return null;
  }
}

export class SSGEngine {
  static async fromOptions(options: EngineOptions, ...extra: Plugin[]): Promise<SSGEngine> {
    let base: Plugin[];
    if (options.plugins && options.plugins.length > 0) {
      base = [...options.plugins];
    } else {
      const config = await loadConfig(options.configFile);
      if (config && Array.isArray(config.plugins) && config.plugins.length > 0) {
        base = [...config.plugins];
      } else {
        base = defaultPlugins();
      }
    }
    const merged: Plugin[] = [];
    for (const plugin of [...base, ...extra]) {
      if (!merged.some((existing) => existing.name === plugin.name)) {
        merged.push(plugin);
      }
    }
    return new SSGEngine(merged);
  }

  readonly pipeline: PluginPipeline;

  constructor(plugins: Plugin[] = []) {
    this.pipeline = new PluginPipeline();
    for (const plugin of plugins) {
      this.pipeline.use(plugin);
    }
  }

  async build(options: BuildOptions): Promise<Page[]> {
    const ctx: PluginContext = {
      options,
      pages: [],
      outputs: new Map(),
      shared: new Map(),
    };

    await this.pipeline.runStart(ctx);
    await this.pipeline.runBeforeBuild(ctx);
    for (const page of ctx.pages) {
      await this.pipeline.runOnFile(page, ctx);
    }
    await this.pipeline.runAfterBuild(ctx);

    await fs.mkdir(options.outputDir, { recursive: true });
    const writes: Promise<void>[] = [];
    for (const [relative, html] of ctx.outputs) {
      writes.push(fs.writeFile(path.join(options.outputDir, relative), html, 'utf8'));
    }
    await Promise.all(writes);

    await this.pipeline.runOnEnd(ctx);
    return ctx.pages;
  }
}

